$ErrorActionPreference = "Stop"

$notes = @(
    "Обновлятор: скачанный архив проверяется ДО применения — версия внутри него обязана совпасть с версией из манифеста, иначе архив отвергается. Раньше версия полного пакета узнавалась только после замены файлов, и подсунутый сервером раздачи архив прошлого релиза молча откатывал программу",
    "Обновлятор: пакет без исполняемого файла программы (motion.exe / Win11CopyDialog.exe) больше не применяется — иначе библиотеки заменились бы, а запускать было бы нечего",
    "Обновлятор: перед загрузкой и перед распаковкой проверяется свободное место; при нехватке сообщаются три числа — нужно, свободно, не хватает",
    "Обновлятор: размеры пакета больше не выдумываются. Если манифест не сообщил размер, интерфейс пишет «размер уточнится при загрузке», а точные цифры появляются из заголовков ответа",
    "Исправлено: Win11CopyDialog/MainWindow.xaml.cs не компилировался — в коммите 27b1c22 остались литеральные \n вместо переводов строк. Горячая клавиша Ctrl+P и окно предпросмотра темы снова работают",
    "Удалены фиктивные артефакты 3.8.56 (Patch.zip 161 байт с одним patch-readme.txt и Setup.exe 24 байта с текстом-заглушкой), из-за которых живой канал предлагал нерабочее обновление",
    "Диагностика: 20/20 тестов обновлятора (включая новые проверки версии пакета, состава и свободного места), 18/18 тестов игрового модуля, 23/23 экрана, сборка без ошибок и предупреждений"
)

& "$PSScriptRoot\Publish-Release.ps1" -Version 3.8.57 -SkipPush -Notes $notes
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
